require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}$rows=pg_query($conn,'SELECT l.*,a.full_name admin_name,a.role FROM audit_logs l LEFT JOIN admins a ON a.id=l.admin_id ORDER BY l.created_at DESC LIMIT 500');admin_page_start('Audit Logs','audit');?><div class="hero"><div><h2><i class="fas fa-clock-rotate-left"></i> Account & System Audit Logs</h2><p>Latest 500 administrative, attendance, account, approval, and finance actions.</p></div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Account</th><th>Action</th><th>Target</th><th>IP Address</th><th>Details</th></tr></thead><tbody><?php if($rows):while($l=pg_fetch_assoc($rows)):?><tr><td><?=h(date('M j, Y g:i:s A',strtotime($l['created_at'])))?></td><td><?=h($l['admin_name']?:'Student/System')?><div class="help"><?=h($l['role']?:'')?></div></td><td><strong><?=h(str_replace('_',' ',$l['action']))?></strong></td><td><?=h(($l['target_type']?:'—').' '.($l['target_id']?:''))?></td><td><?=h($l['ip_address']?:'—')?></td><td><code><?=h($l['details'])?></code></td></tr><?php endwhile;endif;?></tbody></table></div></div><?php admin_page_end();?>
